using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Catamailer.Application.Services;
using Catamailer.Domain;

namespace Catamailer.Application.ViewModels
{
    /// <summary>
    /// ViewModel responsable de la gestion des écarts de synchronisation entre Outlook et Catamailer.
    /// </summary>
    public class CategorySyncViewModel
    {
        private readonly ICategorySyncService _syncService;
        private readonly ICategoryRepository _categoryRepository;
        private readonly ICategoryManagerProvider _outlookProvider;

        /// <summary>
        /// Indique si des conflits de synchronisation ont été détectés.
        /// </summary>
        public bool HasConflicts { get; private set; }

        /// <summary>
        /// Liste des options pour les catégories manquantes dans la base de données Catamailer.
        /// </summary>
        public List<SyncDeltaOption> MissingInCatamailerOptions { get; private set; } = new();

        /// <summary>
        /// Liste des options pour les catégories manquantes dans Outlook.
        /// </summary>
        public List<SyncDeltaOption> MissingInOutlookOptions { get; private set; } = new();

        /// <summary>
        /// Liste des options pour les catégories présentant un conflit de couleur.
        /// </summary>
        public List<SyncDeltaOption> ColorMismatchOptions { get; private set; } = new();

        /// <summary>
        /// Initialise une nouvelle instance de <see cref="CategorySyncViewModel"/>.
        /// </summary>
        /// <param name="syncService">Le service d'analyse de synchronisation.</param>
        /// <param name="categoryRepository">Le dépôt SQLite des catégories.</param>
        /// <param name="outlookProvider">Le fournisseur Outlook COM.</param>
        public CategorySyncViewModel(
            ICategorySyncService syncService,
            ICategoryRepository categoryRepository,
            ICategoryManagerProvider outlookProvider)
        {
            _syncService = syncService;
            _categoryRepository = categoryRepository;
            _outlookProvider = outlookProvider;
        }

        /// <summary>
        /// Charge les écarts de synchronisation depuis le service et initialise les listes d'options pour l'IHM.
        /// </summary>
        public async Task InitializeAsync()
        {
            var syncResult = await _syncService.AnalyzeSyncDeltasAsync();

            HasConflicts = syncResult.HasConflicts;

            MissingInCatamailerOptions = syncResult.GetMissingInCatamailer()
                .Select(d => new SyncDeltaOption(d))
                .ToList();

            MissingInOutlookOptions = syncResult.GetMissingInOutlook()
                .Select(d => new SyncDeltaOption(d))
                .ToList();

            ColorMismatchOptions = syncResult.GetColorConflicts()
                .Select(d => new SyncDeltaOption(d))
                .ToList();
        }

        /// <summary>
        /// Applique les résolutions sélectionnées par l'utilisateur aux référentiels respectifs.
        /// </summary>
        public async Task ApplyResolutionsAsync()
        {
            // 1. Ajouter à Catamailer les catégories manquantes (options sélectionnées)
            foreach (var option in MissingInCatamailerOptions.Where(o => o.IsSelected))
            {
                var newNode = new CategoryNode(option.Delta.CategoryName, option.Delta.OutlookColor);
                await _categoryRepository.AddAsync(newNode);
            }

            // 2. Ajouter à Outlook les catégories manquantes (options sélectionnées)
            foreach (var option in MissingInOutlookOptions.Where(o => o.IsSelected))
            {
                _outlookProvider.AddCategory(option.Delta.CategoryName, option.Delta.CatamailerColor ?? "");
            }

            // 3. Pousser la couleur Catamailer vers Outlook pour les conflits (Catamailer reste maître)
            foreach (var option in ColorMismatchOptions.Where(o => o.IsSelected))
            {
                _outlookProvider.UpdateCategoryColor(option.Delta.CategoryName, option.Delta.CatamailerColor ?? "");
            }
        }
    }
}